let __v_289 = pyrt::literals::decode("{\"$dict\":[[\"guitar\",{\"$dict\":[[\"names\",{\"$tuple\":[\"guitar\",\"guitars\",\"ukulele\",\"uke\",\"banjo\",\"mandolin\"]}],[\"hint\",\"four chords\"],[\"start\",\"Start with four chords that fit a hundred songs — G, C, D and E minor — and the strumming hand before the fretting one. Twenty minutes a day gets you a simple song in two or three months, and six lessons at the start mean nobody has to unlearn your hand position.\"],[\"practise\",\"One song you actually like, in its easiest key: take the chord changes slowly, in a loop, then put them in order. Speed comes last — clean and slow beats fast and sloppy every time.\"],[\"how_long\",\"With 15–20 minutes a day, four chords and a simple song come together in about a month, and something recognisable with a few more chords in three to six months.\"],[\"how_often\",\"Fifteen to twenty minutes a day, five or six days a week, beats one long session at the weekend: the chord changes are what need repeating, and your fingertips need the odd rest day more than the extra minutes. Ten minutes is enough on a busy day - the streak matters more than the length.\"]]}],[\"piano\",{\"$dict\":[[\"names\",{\"$tuple\":[\"piano\",\"pianos\",\"keyboard\",\"keyboards\",\"electric piano\"]}],[\"hint\",\"right hand\"],[\"start\",\"Start with the right hand alone on a song you already know, one note at a time, and the left hand on two or three chords to go with it: hands separately for the first few weeks is not cheating, it is how everyone does it. Twenty minutes a day, and a teacher for the first month so your hand shape is right.\"],[\"practise\",\"Right hand alone, slowly, on a tune you already know by ear — then the same bars with the left hand, then both together much slower than either felt. Five minutes of that daily beats an hour on Sunday.\"],[\"how_long\",\"With 15–20 minutes a day, a simple tune with the right hand comes together in a few weeks, and both hands in three to six months — faster than most people expect, because the notes are laid out in front of you.\"],[\"how_often\",\"Twenty minutes a day, five or six days a week, and shorter on a bad day rather than skipping it: ten focused minutes of scales and one bar done slowly is worth more than an hour on Sunday evening. Keep a day off.\"]]}],[\"violin\",{\"$dict\":[[\"names\",{\"$tuple\":[\"violin\",\"violins\",\"viola\",\"fiddle\",\"cello\"]}],[\"hint\",\"open strings\"],[\"start\",\"Start with the bow and the open strings: long, slow bow strokes on one string are the first month, because a straight bow and a steady sound come before any tune. Ten minutes a day, and a teacher from the first week — this is the instrument where a bad habit is hardest to undo.\"],[\"practise\",\"Open strings with a long, even bow, then one finger at a time on the D and A strings: it sounds dreadful for a few weeks and that is the normal sound of learning. A teacher's ear in the room is worth more here than on any other instrument.\"],[\"how_long\",\"Expect a few months of short tunes on one or two strings, and about a year before something sounds like the tune you set out to play: the bow is the slow part, not the fingers.\"],[\"how_often\",\"Ten to fifteen minutes a day, every day if you can, because it is the bow arm and the intonation that have to repeat - a week off costs you more on the violin than on any other instrument. Stop while it still sounds good rather than practising tired.\"]]}],[\"flute\",{\"$dict\":[[\"names\",{\"$tuple\":[\"flute\",\"flutes\",\"recorder\",\"piccolo\"]}],[\"hint\",\"head joint\"],[\"start\",\"Start with the mouth, not the tune: getting a clean sound out of the head joint is the first week, then long notes on a few fingerings. Ten minutes a day, and a teacher early, because the embouchure is the thing that is hard to fix yourself.\"],[\"practise\",\"Long notes on each fingering, from the easiest note upwards, listening for a steady sound: five minutes of that a day before any tune. Then a short tune in the easy keys, slowly.\"],[\"how_long\",\"A clean sound takes a few weeks, a simple tune two or three months, and something you would play for someone else six months to a year.\"],[\"how_often\",\"Ten to fifteen minutes a day is plenty, most days: five of long notes and the awkward fingering, then a short tune. Daily is what settles the embouchure, and a day off now and then does no harm - a tired mouth is where squeaks come from.\"]]}],[\"reed\",{\"$dict\":[[\"names\",{\"$tuple\":[\"clarinet\",\"sax\",\"saxophone\",\"trumpet\",\"oboe\",\"bassoon\",\"trombone\",\"cornet\",\"horn\",\"french horn\",\"bugle\"]}],[\"hint\",\"mouthpiece\"],[\"start\",\"Start with the mouth: a clean, steady note on the mouthpiece alone is the first week, and long notes on a few fingerings after that. Ten minutes a day, and a teacher early, because the embouchure is the thing that is hard to fix yourself.\"],[\"practise\",\"Long notes, from the easiest note upwards, listening for a steady sound and a clean start to each one: five minutes of that a day before any tune. Then a short tune in the easy keys, slowly.\"],[\"how_long\",\"A clean sound takes a few weeks, a simple tune two or three months, and something you would play for someone else six months to a year.\"],[\"how_often\",\"Ten to fifteen minutes a day, most days: long notes and a clean start to each one first, then a tune. Daily repetition is what builds the embouchure, and the mouth is what gives out first if you push it.\"]]}]]}")?;
frame.store("INSTRUMENTS", __v_289.clone())?;
let __v_290 = pyrt::literals::decode("{\"$dict\":[[\"start\",\"Start with a teacher or a good app for the first month and ten or fifteen minutes a day on the basics: every instrument has its own awkward first fortnight, and one lesson early saves months of undoing. Pick one short piece you like as the target.\"],[\"practise\",\"Whatever is awkward on it — the first clean note, the hand position, the breathing — ten minutes a day, then a short piece slowly. Speed comes last.\"],[\"how_long\",\"With 15–20 minutes a day, a simple tune is usually a few months and something recognisable six months to a year, depending on the instrument.\"],[\"how_often\",\"Short and often: ten to twenty minutes a day, most days of the week, beats one long session at the weekend. Whatever is awkward in it gets the first five minutes, and stopping while it is still going well is what keeps you coming back to it.\"]]}")?;
